/*
 * A check-in's answers in the reader's words (DBU-10). The questions are the answer's own copy of its
 * form, so an old answer always reads against the questions it was given to. A question that was
 * hidden by its condition and has no answer is left out; one that was asked and left empty reads
 * "No answer". A pick reads as its option's words; a scale as "4 of 5".
 */
if (Inputs.questions === undefined || Inputs.answers === undefined) return;
const prefix = String(Inputs.prefix || 'x');
const qs = (Array.isArray(Inputs.questions) ? Inputs.questions : []).filter((q) => q && q.id);
const a = Inputs.answers && typeof Inputs.answers === 'object' ? Inputs.answers : {};
const has = (v) => !(v === undefined || v === null || v === '' || (Array.isArray(v) && !v.length));
const holds = (c) => {
  if (!c || !c.field) return true;
  const v = a[c.field];
  if (Array.isArray(c.value)) return c.value.includes(v);
  if (c.operator) {
    const n = Number(v);
    if (v === undefined || !Number.isFinite(n)) return false;
    return c.operator === '>' ? n > c.value : c.operator === '<' ? n < c.value : c.operator === '>=' ? n >= c.value : c.operator === '<=' ? n <= c.value : false;
  }
  if (c.not !== undefined) return v !== c.not;
  return v === c.value;
};
const words = (q, v) => {
  const opts = Array.isArray(q.options) ? q.options : [];
  const one = (x) => { const o = opts.find((p) => (p && typeof p === 'object' ? p.value : p) === x); return o && typeof o === 'object' ? String(o.label || x) : String(x); };
  return Array.isArray(v) ? v.map(one).join(', ') : one(v);
};
const rows = [];
qs.forEach((q) => {
  const v = a[q.id];
  const row = { id: 'ca-' + prefix + '-' + q.id, label: String(q.label || q.id), value: '', max: '', suffix: '', answerFg: 'var(--foreground)' };
  if (!has(v)) {
    if (!holds(q.condition)) return;
    rows.push(Object.assign(row, { answerKey: 'checkin.answerNone', answerFg: 'var(--muted-foreground)' }));
  } else if (q.type === 'scale') {
    rows.push(Object.assign(row, { answerKey: 'checkin.answerScale', value: String(v), max: String(Number.isFinite(q.max) ? q.max : 5) }));
  } else if (q.type === 'number') {
    rows.push(Object.assign(row, { answerKey: q.suffix ? 'checkin.answerNumber' : 'checkin.answerValue', value: String(v), suffix: String(q.suffix || '') }));
  } else if (q.type === 'radio' || q.type === 'checkbox') {
    rows.push(Object.assign(row, { answerKey: 'checkin.answerValue', value: words(q, v) }));
  } else {
    rows.push(Object.assign(row, { answerKey: 'checkin.answerValue', value: String(v) }));
  }
});
Outputs.rows = rows;
